const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const phoenix = ee.Geometry.Point([-112.0740, 33.4484]);
  const startDate = '2023-06-01';
  const endDate = '2023-08-31';
  const tempThresholdF = 110; // Fahrenheit

  // 2. Data Acquisition
  const modisLST = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(phoenix)
    .select('LST_Day_1km', 'QC_Day');

  // Check if collection is empty (C1)
  const collectionSize = modisLST.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No MODIS images found for Phoenix from ${startDate} to ${endDate}.`);
    console.log("A: No");
    return;
  }
  console.log(`Found ${collectionSize} potential images in summer 2023.`);

  // 3. Processing Functions
  // Function to mask low-quality pixels
  const maskLST = function(image) {
    const qc = image.select('QC_Day');
    // Bits 0-1: Mandatory QA flags. 00 = Good data.
    const qualityMask = qc.bitwiseAnd(0b11).eq(0);
    return image.updateMask(qualityMask);
  };

  // Function to convert Kelvin to Fahrenheit
  const kelvinToFahrenheit = function(image) {
    const lstF = image.select('LST_Day_1km')
      .multiply(0.02) // Apply scale factor
      .subtract(273.15) // Kelvin to Celsius
      .multiply(9/5)
      .add(32) // Celsius to Fahrenheit
      .rename('LST_F');
    return image.addBands(lstF);
  };

  // Apply processing to the collection
  const processedLST = modisLST.map(maskLST).map(kelvinToFahrenheit);

  // 4. Calculation
  // Get a list of dates and mean temperatures
  const dailyTemps = processedLST.map(function(image) {
    const meanTemp = image.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: phoenix,
      scale: 1000,
      maxPixels: 1e9
    });
    return ee.Feature(null, {
      'date': image.date().format('YYYY-MM-dd'),
      'tempF': meanTemp.get('LST_F')
    });
  }).filter(ee.Filter.notNull(['tempF'])); // Remove days with no valid pixels

  // Check for no valid pixels after masking (C2)
  const validDaysCount = dailyTemps.size().getInfo();
  if (validDaysCount === 0) {
      console.log("No valid (cloud-free) LST pixels found for Phoenix during the period.");
      console.log("A: No");
      return;
  }
  console.log(`Found ${validDaysCount} days with valid LST data.`);

  const dailyTempsList = dailyTemps.reduceColumns(ee.Reducer.toList(2), ['date', 'tempF']).get('list').getInfo();

  let maxConsecutiveDays = 0;
  let currentConsecutiveDays = 0;

  for (const dayData of dailyTempsList) {
      const date = dayData[0];
      const temp = dayData[1];
      if (temp > tempThresholdF) {
          currentConsecutiveDays++;
      } else {
          if (currentConsecutiveDays > maxConsecutiveDays) {
              maxConsecutiveDays = currentConsecutiveDays;
          }
          currentConsecutiveDays = 0; // Reset counter
      }
  }
  // Final check in case the streak was at the end of the period
  if (currentConsecutiveDays > maxConsecutiveDays) {
      maxConsecutiveDays = currentConsecutiveDays;
  }

  // 5. Validation & Final Answer
  console.log(`Threshold Temperature: ${tempThresholdF}°F`);
  console.log(`Longest consecutive streak of days above threshold: ${maxConsecutiveDays}`);

  if (maxConsecutiveDays >= 40) {
    console.log("A: Yes");
  } else {
    console.log("A: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error(err);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
